    ExcelVisualizerWidget.prototype.paintVisualizer = function() {
        this.config = this._generateConfig();
        this._initTemplate();
        if (Object.keys(this.config).length === 0){
            return;
        }
        let datatableColums = this._initTables(this.config);
        let dataTablesValues = this._initInfo(this.config);
        for (i = 0; i < datatableColums.length; i++) {
            this.viewTable(datatableColums[i], dataTablesValues[i])
        } 
    }
    ExcelVisualizerWidget.prototype._generateConfig = function () {
        let nodeId = WebGMEGlobal.State.getActiveObject();
        let configuration = {};
        if ( typeof(nodeId) !== "undefined" && nodeId !== null ) {
            let node = this._client.getNode(nodeId);
            if (!node){
                return configuration;
            }
            let idMetanode = node.getMetaTypeId();

            let libraryRootNode = idMetanode && idMetanode.split('/').length > 2 ?'/'+idMetanode.split('/')[1]: '';
            let attributeName = this._obtainConfigAttribute(nodeId);
            try{
                let config = node.getAttribute(attributeName); 
                if ( typeof(attributeName) !== "undefined" && attributeName !== null && Object.keys(JSON.parse(config)).length !== 0) {
                    configuration = JSON.parse(config);
                    configuration = this._fixPaths(configuration, libraryRootNode);
                } else{ 
                    configuration=excelConfig.autoGenerateConfig(nodeId, node, this._client);
                }
            }catch (error) {
                if (typeof(node) !== "undefined" && node !== null){
                    configuration = excelConfig.autoGenerateConfig(nodeId, node, this._client);
                }
            }
        }
        return configuration;
    };
   
    ExcelVisualizerWidget.prototype._fixPaths = function(config, rootPath){
        
        config.node.metaPath = rootPath+config.node.metaPath
        let metaNode = this._client.getNode(config.node.metaPath);
        config.node.guid = metaNode.getGuid();
        config.children = config.children.map(node =>{
            let path = rootPath+node.metaPath;
            let metaNodeChild = this._client.getNode(path);
            return {
                ...node,
                metaPath: path,
                guid: metaNodeChild.getGuid(),
            }
        })
        return config
    }
    ExcelVisualizerWidget.prototype._obtainConfigAttribute = function(nodeId){
        let attribute = null;
        let node = this._client.getNode(nodeId);
        if (node == null){
            WebGMEGlobal.State.registerActiveVisualizer('ModelEditor');
        }else{
            node.getAttributeNames().forEach(attributeName=>{
                let attributeNode = node.getAttributeMeta(attributeName);
                if (attributeNode && attributeNode.type === 'config'){
                    attribute = attributeName;
                }
            })
        }
        return attribute;
    }
    ExcelVisualizerWidget.prototype._initTemplate = function () {
        let self = this;
        this._el.addClass(WIDGET_CLASS);
        this._el.empty();
        this._el.addClass('mbse4sdv-form-widget');
        this._el.append(excelTemplate);

    };
    ExcelVisualizerWidget.prototype._initInfo = function (config) {
        let self = this;
        let nodeId = WebGMEGlobal.State.getActiveObject();
        let dataTable = [];
        let valueDetail = [];
        if (config.node && !config.node.form){
            valueDetail.push(this._detailValue(config.node, nodeId, false));
            dataTable.push(valueDetail);
        }else{
            self._el.find('#buttonSave'+config.node.guid).click(function () {
                let nodeForm = self.obtainFormObject(document.getElementById('form'+config.node.guid).elements);
                self.operateForm(nodeForm);    
            });
            self._el.find('#form'+config.node.guid).submit(function() { 
                let nodeForm = self.obtainFormObject(document.getElementById('form'+config.node.guid).elements);
                self.operateForm(nodeForm);
                return false;
            });
        }

        config.children.forEach(child =>{
            if(!child.form){
                dataTable.push(this._generateAllChildType(child, nodeId));
            }else{
                self._el.find('#buttonSave'+child.guid).click(function () {
                    let nodeForm = self.obtainFormObject(document.getElementById('form'+child.guid).elements);
                    self.operateForm(nodeForm);
                });
                self._el.find('#form'+child.guid).submit(function(e) {
                    let nodeForm = self.obtainFormObject(document.getElementById('form'+child.guid).elements);
                    self.operateForm(nodeForm);
                    return false;
                })
            }
        });
        return dataTable;
    };
    ExcelVisualizerWidget.prototype.operateForm = function (nodeForm){
        let self = this;
        if (nodeForm.id) {
            self._client.startTransaction();
            Object.keys(nodeForm.fields).forEach(key =>{
                self._client.setAttribute(nodeForm.id, key, nodeForm.fields[key]);
            });
            self._client.completeTransaction();
        }else{
            self._client.createNode({
                baseId: nodeForm.baseId,
                parentId: WebGMEGlobal.State.getActiveObject(),
            }, {attributes: nodeForm.fields},
            'Model \'' + nodeForm.baseId + '\' created by ExcelVisualizer');
        }
    }
    ExcelVisualizerWidget.prototype.obtainFormObject = function (form){
    
        let fields = {};
        let nodeForm = {
            fields: fields,
        };
        for (let i = 0; i < form.length; i++) {
            if (form[i].nodeName === "INPUT" && form[i].type !== 'button') {
                switch (form[i].name){
                    case 'id':  form[i].value !== "null" ?nodeForm.id = form[i].value : null; break;
                    case 'baseId': nodeForm.baseId = form[i].value; break;
                    default:  nodeForm.fields[form[i].name] = form[i].value;
                }
            }
        }
        return nodeForm;
    }
    ExcelVisualizerWidget.prototype._detailValue = function (config,id, isChild) {
        let node = this._client.getNode(id);
        let guid = node.getGuid();
        let values = {};
         config.attributes.map(attribute=>{
            let value = node.getAttribute(attribute.name);
            values[""+attribute.name]= '<input type="text" id="'+config.guid;
            if(isChild){
                values[""+attribute.name]+= '_child';
            }
            values[""+attribute.name]+="_"+guid+'_'+attribute.name+'" name="row-1-age" value="'+value+'">';
        })
        values["pathId"] = id;
        return values;

    }
    ExcelVisualizerWidget.prototype._generateAllChildType = function(config,id){
        let node = this._client.getNode(id);
        let childrens = node.getChildrenIds();
        let values = [];
        childrens.forEach(childId=>{
            let childNode = this._client.getNode(childId);
            if (childNode && config.metaPath === childNode.getMetaTypeId()){
                values.push(this._detailValue(config, childId, true));
            }
        });
        return values;
    }
   
    ExcelVisualizerWidget.prototype._initTables = function (config) {
        let elementHTMl = this._el.find('#bodyElement')[0];
        let columnsDataTables = []
        if (config.node && !config.node.form  && config.node.vissible){
            columnsDataTables.push({
                id: config.node.guid,
                metaPath: config.node.metaPath,

                columns: this.createTable(config.node, elementHTMl, "<h3>Element modified: "+config.node.title+"</h3>", false)
            });
        }else if(config.node.form ){
            this.createForm(config.node, elementHTMl, "<h3>Element modified: "+config.node.title+"</h3>", WebGMEGlobal.State.getActiveObject())
        }
        config.children.forEach(childrenGroup=>{
            if(childrenGroup.form){
                let nodeId = this.obtainChildrenId(childrenGroup.id, WebGMEGlobal.State.getActiveObject())
                this.createForm(childrenGroup, elementHTMl, "<h3>Element modified: "+childrenGroup.title+"</h3>", nodeId)
            }else{
                columnsDataTables.push({
                    id: childrenGroup.guid+"_child",
                    metaPath: childrenGroup.metaPath,
                    columns: this.createTable(childrenGroup, elementHTMl, "<h4>"+childrenGroup.title+"</h4>", true)
                });
            }
        });
        return columnsDataTables;
    };
    ExcelVisualizerWidget.prototype.obtainChildrenId = function (referenceId, parentId) {
        let  childId = null;
        let paretNode = this._client.getNode(parentId);
        let childrensIds = paretNode.getChildrenIds();
        childrensIds.forEach(pathChild=>{
            let childNode = this._client.getNode(pathChild);
            let childMetaId = childNode ? childNode.getMetaTypeId() :null;
            if(childMetaId && childMetaId === referenceId){
                   childId = pathChild; 
            }
        })
        return childId;
    }
    ExcelVisualizerWidget.prototype.createTable = function (actualNode, elementHTML, title, isChild){
        let self = this;
        let tableHeader = '<div class="row">';
        tableHeader += '<div class="col-sm-3" id="title_'+actualNode.guid+'">'+title+'</div>';
        tableHeader += '<div class="col-sm-3" ></div>';
        if(isChild){
            tableHeader += '<div class="col-sm-3"  id="button_'+actualNode.guid+'"><button id="create'+actualNode.guid+'_childButton" class="btn btn-secondary">Create new '+actualNode.title+'</button></div>';
        }
        tableHeader +='</div>';
        elementHTML.innerHTML += tableHeader;
        let columns = [];
        let bodyTable = "<table id='"+actualNode.guid;
        bodyTable += isChild ? "_child' class='display'>" :"' class='display'>";
        bodyTable +="<thead>";
        bodyTable +=" <tr id='"+actualNode.guid+"headerRow'>";
        let columnWidth = actualNode.attributes.length > 0 ? Math.floor(100/actualNode.attributes.length) : 100;
        actualNode.attributes.forEach(attribute=>{
            let cellHTML = "<th style='width: "+columnWidth+"%;''>"+attribute.name+"</th>";
            bodyTable +=cellHTML;
            columns.push({ data: attribute.name })
        })
        bodyTable += "<th></th>"; 
        bodyTable += "<th></th>"; 
        bodyTable += "<th></th>"; 
        columns.push({
            data: null,
            defaultContent: '<i class="fa fa-floppy-o"/>',
            className: 'row-edit dt-center',
            orderable: false
        });
        columns.push({
            data: null,
            defaultContent: '<i class="fa fa-trash"/>',
            className: 'row-remove dt-center',
            orderable: false
        });
        columns.push(
            {
                data: null,
                className: "dt-center row-refresh",
                defaultContent: '<i class="fa fa-refresh"/>',
                orderable: false
        })
        bodyTable +=" </tr>";
        bodyTable +=" </thead>";
        bodyTable +=" <tbody id='"+actualNode.guid+"body'>";
    
        bodyTable +=" </tbody>";
        bodyTable +=" </table>";
        elementHTML.innerHTML += bodyTable;
       
       
        return columns;
    }
    
    ExcelVisualizerWidget.prototype.createForm = function (actualNode, elementHTML, title, id){
        let self = this;
        if (!actualNode.vissible){
            return;
        }
        let node = self._client.getNode(id);
        let form = '<div class="divForm">';
        let formHeader = '<div class="row">';
        formHeader += '<div class="col-sm-12" id="title_'+actualNode.guid+'">'+title+'</div>';
        formHeader +='</div>';
        form += formHeader;
        let formBody = '<form id="form'+actualNode.guid+'"><div class="row">';
        let column1 = ' <div class="col-sm-6">';
        let column2 = ' <div class="col-sm-6">';
       
        actualNode.attributes.forEach((attribute, index)=>{
            let value = node ?  node.getAttribute(attribute.name) : '';// = node.getAttribute(attribute.name);
            let cellHTML = '<div class="form-group">';
            cellHTML+='<label for="form" class="col-md-3 control-label">';
            cellHTML+='<strong><spanaria-hidden="true">'+attribute.name+'</span></strong>';
            cellHTML+='</label>';
            cellHTML+=self.getAttributeForm(attribute,value );
            cellHTML+='</div>';

            (index % 2 === 0) ? column1 += cellHTML : column2 += cellHTML;
        })
        column1 +='</div>';
        column2 +='</div>';
        formBody += column1;
        formBody += column2;
        formBody += '</div>';
        formBody += '<div class="row"><div class="col-sm-6">';
        formBody += '<input type="hidden" id="id" name="id" value="'+id+'"/>';
        formBody += '<input type="hidden" id="baseId" name="baseId" value="'+actualNode.metaPath+'"/>';
        formBody += '</div><div class="col-sm-6"><input type="button" id="buttonSave'+actualNode.guid+'" class="btn btn-secondary" value="Save"></div></div>';
        formBody += '</form>';
        form += formBody+'</div>';
        elementHTML.innerHTML += form;

    }
    ExcelVisualizerWidget.prototype.getAttributeForm = function (attribute, value) {
        switch (attribute.representation){
            case 'integerInput': return '<input type="integer" id="'+ attribute.name +'" name="'+ attribute.name +'" class="form-control"  value="'+value+'"/>';
            default: return '<input type="text" id="'+ attribute.name +'" name="'+ attribute.name +'" class="form-control" placeholder="'+ attribute.name +'" value="'+value+'"/>';
            /*case "integer":attributeNode.representation = "integerInput"; break;
            case "float": attributeNode.representation = "floatInput"; break;
            case "boolean": attributeNode.representation = "booleanInput"; break;
            case "asset": attributeNode.representation = "fileInput"; break;
            default: 
                if(attributeNode.multiline){
                    attributeNode.representation = "multiLineInput";
                    attributeNode.lenguaje = attributeNode.multilineType;break; 
                }else if (attributeNode.enum){
                    attributeNode.representation = "select";
                    attributeNode.options = attributeNode.enum;
                }else{
                    attributeNode.representation = "inputText";
                }*/
        }
    }
    ExcelVisualizerWidget.prototype.viewTable = function (metadata, values) {
       let self = this;
        // Activate an inline edit on click of a table cell
        $("#"+metadata.id).on( 'click', 'tbody td.row-edit', function (e) {
            let index = $(this).closest('tr').index();
            var data = table.row(index).data();
            let auxData = {};
            let node = Object.keys(data).includes('pathId') ?  self._client.getNode(data.pathId): {}
            let guid = Object.keys(data).includes('pathId') ? node.getGuid() : '';

            Object.keys(data).forEach(key =>{
                auxData[key] = {};
                if(key ==='pathId' || key ==='metaPath'){
                    auxData[key].value = data[key];
                    auxData[key].attributeName = key;
                }else{
                    if (Object.keys(data).includes('pathId')){
                        auxData[key].value =  $("#"+metadata.id+'_'+guid+'_'+key).val()
                    }else{
                        auxData[key].value =  $("#"+metadata.id+'_'+key).val();
                    }
                    auxData[key].attributeName = key;
                }
            })
            self.onEdit(data.pathId, auxData);
        } );
     
        // Delete row
        $("#"+metadata.id).on( 'click', 'tbody td.row-remove', function (e) {
            var data = table.row($(this).parents('tr')).data();
            self.onDelete(data.pathId);
            $("#"+metadata.id).DataTable().row( $(this).closest('tr').index()).remove().draw();
        } );
        var table = $("#"+metadata.id).DataTable({
            columns: metadata.columns,
            "searching": false,
            "ordering": false,
        });
        $("#"+metadata.id).on( 'click', 'tbody td.row-refresh', function (e) {
            let index = $(this).closest('tr').index();
            let data = table.row($(this).parents('tr')).data();
            let node = self._client.getNode(data.pathId);
            let metaId = node.getMetaTypeId();
            let metaNode = self._client.getNode(metaId);
            let values = {};
            if (Object.keys(data).includes('pathId')){
                node.getAttributeNames().forEach(attributeName=>{
                    let attributeNode = metaNode.getAttributeMeta(attributeName);
                    if (!attributeNode.hidden){
                        let value = node.getAttribute(attributeName);
                        values[""+attributeName]= '<input type="text" id="'+metadata.pathId+'_'+node.getGuid()+'_'+attributeName+'" name="row-1-age" value="'+value+'">';
                    }
                })
                values["pathId"] = data.pathId;
                table.row(index).data( values )
            }else{
                $("#"+metadata.pathId).DataTable().row(index).remove().draw();
            }
        } );
        this._el.find('#create'+metadata.id+'Button').click(function () {
            self.onCreate(metadata.metaPath, table);
            
        });
        values.forEach(value=>table.row.add(value).draw(true));

    }

